import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PIN_LIST = [2, 3, 4]
POLL_INTERVAL = 60

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def apply_states(pin_devices):
    for pin in pin_devices:
        try:
            pin.on()
            print(f"GPIO {pin.pin.number} -> ON")
        except DeviceClosed:
            print(f"Error: GPIO {pin.pin.number} is closed.", file=sys.stderr)
            return False
        except Exception as exc:
            print(f"Error writing GPIO {pin.pin.number}: {exc}", file=sys.stderr)
            return False
    return True


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    pin_devices = []
    try:
        for pin in PIN_LIST:
            dev = OutputDevice(pin)
            pin_devices.append(dev)
            print(f"Initialized GPIO {pin} as output.")
    except GPIOZeroError as exc:
        print(f"Error: Failed to initialize GPIO pins: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error during initialization: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            apply_states(pin_devices)
            if not _running:
                break
            time.sleep(POLL_INTERVAL)
    finally:
        for dev in pin_devices:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

import time
