import sys
from luma.core.interface.serial import i2c
from luma.core.render import canvas
from luma.oled.device import ssd1306

# Configuration
DEVICE_I2C_ADDRESS = 0x3C
READ_INTERVAL_SECONDS = 2
NUM_READINGS = 5

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def initialize_display():
    """Initialize the SSD1306 display over I2C."""
    try:
        serial = i2c(port=1, address=DEVICE_I2C_ADDRESS)
        device = ssd1306(serial)
        return device
    except Exception as e:
        print(f"Error initializing display: {e}", file=sys.stderr)
        return None


def read_sensor_data():
    """Simulate reading sensor data. Replace with actual sensor code."""
    return [int(time.time()), 25, 50]


def display_data(device, data):
    """Display sensor data on the SSD1306 display."""
    try:
        with canvas(device) as draw:
            draw.text((0, 0), f"Temp: {data[0]} C", fill="white")
            draw.text((0, 12), f"Light: {data[1]} Lux", fill="white")
            draw.text((0, 24), f"Motion: {data[2]} Events", fill="white")
    except Exception as e:
        print(f"Error displaying data: {e}", file=sys.stderr)


def main():
    """Main function to run the sensor reading and display loop."""
    global _running

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    device = initialize_display()
    if device is None:
        sys.exit(1)

    try:
        for i in range(NUM_READINGS):
            if not _running:
                break

            data = read_sensor_data()
            if not data:
                print("No data received from sensor.", file=sys.stderr)
                continue

            try:
                display_data(device, data)
            except Exception as e:
                print(f"Error during display update: {e}", file=sys.stderr)

            if i < NUM_READINGS - 1 and _running:
                time.sleep(READ_INTERVAL_SECONDS)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        # Clean resource release on all exit paths
        try:
            device.cleanup()
        except Exception:
            pass


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

PIN_LIST = [1, 2, 3, 4]
INTERVAL = 0.1
running = True


def handle_signal(signum, frame):
    global running
    running = False


def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    devices = []
    try:
        for pin in PIN_LIST:
            dev = PWMOutputDevice(pin, frequency=1000, initial_value=0)
            devices.append(dev)
    except GPIOZeroError as exc:
        print(f"Failed to initialize PWM on GPIO {PIN_LIST}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            values = [float(v) for v in input().split()]
            if len(values) != len(PIN_LIST):
                print("Error: number of values must match number of pins.")
                continue
            if not all(0.0 <= v <= 1.0 for v in values):
                print("Error: values must be between 0.0 and 1.0.")
                continue
            for i, v in enumerate(values):
                dev = devices[i]
                if not isinstance(v, (int, float)):
                    print(f"Warning: non-numeric value on pin {i}, using 0.0.")
                    dev.value = 0.0
                else:
                    dev.value = v
            print(f"GPIO {PIN_LIST}: {values}")
            time.sleep(INTERVAL)
    finally:
        for dev in devices:
            dev.close()


if __name__ == "__main__":
    main()

import time
import signal
import sys
import logging

try:
    from picamera2 import Picamera2
except ImportError:
    print("Error: picamera2 library is not installed. Install with: pip install picamera2", file=sys.stderr)
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("picamera2_capture")

running = True

def _signal_handler(signum, frame):
    global running
    log.info("Signal %s received, shutting down...", signum)
    running = False

signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)

def capture_image(camera):
    """Capture a single image from the camera and return it as a numpy array."""
    try:
        image = camera.capture_array()
        if image is None or image.size == 0:
            log.error("Captured image is empty.")
            return None
        return image
    except Exception as e:
        log.error("Error capturing image: %s", e)
        return None

def save_image(image, filename):
    """Save the image to a file. Returns True on success, False on failure."""
    try:
        from PIL import Image
        img = Image.fromarray(image)
        img.save(filename)
        return True
    except Exception as e:
        log.error("Error saving image to '%s': %s", filename, e)
        return False

def main():
    camera = None
    try:
        camera = Picamera2()
        camera.start()
        log.info("Camera started successfully.")

        while running:
            image = capture_image(camera)
            if image is None:
                log.warning("Skipping this cycle due to capture failure.")
            else:
                timestamp = time.strftime("%Y%m%d_%H%M%S")
                filename = f"image_{timestamp}.jpg"
                if save_image(image, filename):
                    log.info("Image saved to '%s'", filename)
                else:
                    log.warning("Failed to save image to '%s'", filename)

            if running:
                time.sleep(1)

    except Exception as e:
        log.exception("Fatal error: %s", e)
        sys.exit(1)
    finally:
        if camera is not None:
            try:
                camera.stop()
                log.info("Camera stopped.")
            except Exception as e:
                log.error("Error stopping camera: %s", e)

if __name__ == "__main__":
    main()

