from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

PIN = 17

def main() -> int:
    try:
        output = OutputDevice(PIN)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO {PIN}: {exc}", file=sys.stderr)
        return 1

    def cleanup(signum=None, frame=None) -> None:
        try:
            output.close()
        except Exception:
            pass
        if signum is not None:
            sys.exit(0)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        output.on()
        print(f"GPIO {PIN} set to HIGH")
    except GPIOZeroError as exc:
        print(f"Failed to write GPIO {PIN}: {exc}", file=sys.stderr)
        return 1

    try:
        output.off()
        print(f"GPIO {PIN} set to LOW")
    except GPIOZeroError as exc:
        print(f"Failed to write GPIO {PIN}: {exc}", file=sys.stderr)
        return 1

    cleanup()
    return 0

