import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
TIMEOUT = 1
READ_INTERVAL = 5

running = True

def handle_signal(signum, frame):
    global running
    running = False

def read_device_data(device):
    try:
        data = device.readline().decode('ascii', errors='replace').strip()
        if not data:
            return None
        return data
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected read error: {e}", file=sys.stderr)
        return None

def check_data_validity(data):
    if not data:
        return False
    return True

def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        device = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error opening serial port: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            data = read_device_data(device)
            if data is None:
                print("No data received (timeout or error).", file=sys.stderr)
            elif not check_data_validity(data):
                print(f"Invalid data received: {data}", file=sys.stderr)
            else:
                print(f"Data received: {data}")
            time.sleep(READ_INTERVAL)
    finally:
        device.close()
        print("Serial port closed. Exiting.")

if __name__ == "__main__":
    main()

import time
import signal
import sys
import numpy as np
from picamera2 import Picamera2

running = True

def _signal_handler(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)

def capture_image(picam2):
    """Capture an image from the Raspberry Pi camera and return it as a numpy array."""
    try:
        image = picam2.capture_array()
        if image is None or image.size == 0:
            raise RuntimeError("Captured image is empty")
        if not isinstance(image, np.ndarray):
            raise RuntimeError("Captured image is not a numpy array")
        return image
    except Exception as e:
        print(f"Error capturing image: {e}", file=sys.stderr)
        return None

def save_image(image, filename):
    """Save the captured image to a file."""
    try:
        np.save(filename, image)
        print(f"Image saved to {filename}")
    except Exception as e:
        print(f"Error saving image: {e}", file=sys.stderr)

def main():
    picam2 = None
    try:
        picam2 = Picamera2()
        picam2.start()
        print("Camera started. Capturing images every 1 second. Press Ctrl+C to stop.")

        while running:
            image = capture_image(picam2)
            if image is None:
                time.sleep(1)
                continue

            # Basic validity check: ensure the image is a 2D array with at least 1 row/column
            if image.ndim != 2 or image.size == 0:
                print("Invalid image captured. Skipping.", file=sys.stderr)
                time.sleep(1)
                continue

            filename = "image_array.npy"
            save_image(image, filename)
            time.sleep(1)

    except RuntimeError as e:
        print(f"Camera initialization error: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if picam2 is not None:
            try:
                picam2.stop()
                print("Camera stopped.")
            except Exception as e:
                print(f"Error stopping camera: {e}", file=sys.stderr)

if __name__ == "__main__":
