import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

PIN_A = 17
PIN_B = 27
POLL_INTERVAL = 60  # seconds

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_state(device):
    """Return the current logical state of the device, or None on error."""
    try:
        return int(device.value)
    except Exception as exc:
        print(f"Warning: failed to read device state: {exc}", file=sys.stderr)
        return None

def apply_state(device, state):
    """Apply a logical state to the device, or None on error."""
    try:
        device.value = 1 if state else 0
        return True
    except Exception as exc:
        print(f"Warning: failed to apply state: {exc}", file=sys.stderr)
        return False

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        device_a = OutputDevice(PIN_A)
        device_b = OutputDevice(PIN_B)
    except (GPIOZeroError, GPIODeviceError) as exc:
        print(f"Error: failed to initialize GPIO pins {PIN_A}/{PIN_B}: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Error: unexpected GPIO initialization failure: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            state_a = read_state(device_a)
            state_b = read_state(device_b)

            if state_a is None or state_b is None:
                print("Error: failed to read device state; skipping cycle.", file=sys.stderr)
            else:
                applied_a = apply_state(device_a, state_a)
                applied_b = apply_state(device_b, state_b)

                if applied_a and applied_b:
                    print(f"GPIO A: {state_a} | GPIO B: {state_b}")
                else:
                    print(f"Error: failed to apply state; skipping cycle.", file=sys.stderr)

            # Sleep in small increments so signals are caught promptly
            slept = 0
            while _running and slept < POLL_INTERVAL:
                time.sleep(1)
                slept += 1

    finally:
        for dev in (device_a, device_b):
            try:
                dev.close()
            except Exception:
                pass

if __name__ == "__main__":
    main()

