import time
import signal
import sys
import board
import adafruit_dht

# DHT22 data pins (BCM numbering) on the Raspberry Pi
DATA_PINS = [board.D4, board.D5, board.D17, board.D23]

# Global flag for graceful shutdown
_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_dht22(device, pin):
    """Read temperature and humidity from a DHT22 sensor.

    Returns (temperature, humidity) as floats, or None if the reading
    fails its internal validity check or the device is unresponsive.
    """
    try:
        temperature = device.temperature
        humidity = device.humidity
        if temperature is None or humidity is None:
            return None
        return temperature, humidity
    except RuntimeError as e:
        # DHT22 checksum / timing errors are raised as RuntimeError
        print(f"Read error on pin {pin}: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error on pin {pin}: {e}")
        return None

def apply_state(temperature, humidity):
    """Print the current temperature and humidity state."""
    print(f"Temperature: {temperature:.1f} C, Humidity: {humidity:.1f} %")

def main():
    global _running

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize DHT22 devices on each pin
    devices = []
    for pin in DATA_PINS:
        try:
            device = adafruit_dht.DHT22(pin, use_pulseio=False)
            devices.append(device)
        except Exception as e:
            print(f"Failed to initialize DHT22 on pin {pin}: {e}")
            devices.append(None)

    if not all(devices):
        print("No DHT22 devices initialized. Exiting.")
        sys.exit(1)

    try:
        while _running:
            for device, pin in zip(devices, DATA_PINS):
                if device is None:
                    continue
                result = read_dht22(device, pin)
                if result is None:
                    print(f"Pin {pin}: failed to read valid data")
                    break
            if result is not None:
                apply_state(result[0], result[1])
            # Sleep in small increments so signals are caught promptly
            for _ in range(60):
                if not _running:
                    break
                time.sleep(1)
    finally:
        # Release hardware resources on every exit path
        for dev in devices:
            if dev is not None:
                try:
                    dev.exit()
                except Exception:
                    pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

