import signal
import sys
import board
import busio
import digitalio
import adafruit_mcp3xxx.mcp3008 as MCP
from adafruit_mcp3xxx.analog_in import AnalogIn

SAMPLE_COUNT = 3
SAMPLE_INTERVAL = 60

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_adc(channel: int) -> int:
    """Return a 10-bit ADC reading from the given MCP3008 channel (0-7)."""
    if not 0 <= channel <= 7:
        raise ValueError(f"channel must be 0-7, got {channel}")
    try:
        adc = AnalogIn(MCP.A0, MCP.A1, MCP.A2, channel=channel)
        return int(adc.value)
    except Exception as exc:
        print(f"Error reading ADC channel {channel}: {exc}", file=sys.stderr)
        return None

def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        adc = MCP.MCP3008(i2c, channel=0)
    except Exception as exc:
        print(f"Failed to initialize MCP3008: {exc}", file=sys.stderr)
        return 1

    try:
        for i in range(SAMPLE_COUNT):
            if not _running:
                print("Interrupted by signal.", file=sys.stderr)
                return 130
            try:
                value = read_adc(i)
            except Exception:
                value = None
            if value is None:
                print(f"Reading {i} failed.", file=sys.stderr)
            else:
                print(f"Reading {i}: {value}")
            if i < SAMPLE_COUNT - 1 and _running:
                time.sleep(SAMPLE_INTERVAL)
    except Exception as exc:
        print(f"Unexpected error during sampling: {exc}", file=sys.stderr)
        return 1
    finally:
        try:
            adc.deinit()
        except Exception:
            pass
    return 0

if __name__ == "__main__":
