import serial
import sys
import signal

PORT = '/dev/serial0'
BAUD = 115200
TIMEOUT = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def open_serial():
    try:
        return serial.Serial(PORT, BAUD, timeout=TIMEOUT)
    except serial.SerialException as exc:
        print(f"Error: cannot open serial port {PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

def read_device(ser):
    try:
        line = ser.readline()
    except serial.SerialException as exc:
        print(f"Error: serial read failed: {exc}", file=sys.stderr)
        return None
    if not line:
        return None
    text = line.decode('ascii', errors='replace').strip()
    if not text:
        return None
    return text

def validate_reading(text):
    if not text:
        return False
    if not text.isdigit():
        print(f"Warning: non-numeric reading ignored: {text}", file=sys.stderr)
        return False
    try:
        return int(text) >= 0 and int(text) <= 100
    except ValueError:
        print(f"Warning: out-of-range reading ignored: {text}", file=sys.stderr)
        return False
    return True

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)
    ser = open_serial()
    try:
        while _running:
            reading = read_device(ser)
            if reading is None:
                print("Error: device did not respond within timeout.", file=sys.stderr)
                break
            if not validate_reading(reading):
                print(f"Warning: invalid reading '{reading}' ignored.", file=sys.stderr)
                continue
            print(f"Reading: {reading}")
    finally:
        if ser.is_open:
            ser.close()
            print("Serial port closed.")
    sys.exit(0)

if __name__ == '__main__':
    main()

