import board
import adafruit_dht

# Pin assignments (BCM numbering)
DHT_PINS = [board.D4, board.D7, board.D11, board.D17]

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_dht22(dht_device, pin):
    """Read temperature and humidity from a DHT22 on the given pin.

    Returns (temperature, humidity) as floats, or (None, None) on error.
    """
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            return None, None
        return temperature, humidity
    except RuntimeError as e:
        # DHT22 commonly throws RuntimeError on transient read failures
        return None, None
    except Exception as e:
        print(f"Error reading DHT22 on pin {pin}: {e}", file=sys.stderr)
        return None, None

def apply_state(temperature, humidity):
    """Print the current temperature and humidity state."""
    print(f"Temperature: {temperature:.1f} C, Humidity: {humidity:.1f} %")

def main():
    global _running

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize DHT22 devices; adafruit_dht uses BCM numbering by default
    dht_devices = []
    for pin in DHT_PINS:
        try:
            dht_device = adafruit_dht.DHT22(pin, use_pulseio=False)
            dht_devices.append(dht_device)
        except Exception as e:
            print(f"Failed to initialize DHT22 on pin {pin}: {e}", file=sys.stderr)
            # Clean up any devices that were already created
            for dev in dht_devices:
                try:
                    dev.exit()
                except Exception:
                    pass
            sys.exit(1)

    try:
        while _running:
            for dht_device, pin in zip(dht_devices, DHT_PINS):
                if not _running:
                    break
                temperature, humidity = read_dht22(dht_device, pin)
                if temperature is not None and humidity is not None:
                    apply_state(temperature, humidity)
                    # Check for valid readings
                    if not (-40.0 <= temperature <= 80.0):
                        print("Warning: Temperature out of expected range.", file=sys.stderr)
                    if not (0.0 <= humidity <= 100.0):
                        print("Warning: Humidity out of expected range.", file=sys.stderr)
                else:
                    print("Failed to read from DHT22 on pin", pin, file=sys.stderr)

            # Sleep in small increments to allow prompt signal handling
            for _ in range(50):
                if not _running:
                    break
                time.sleep(0.1)

    finally:
        # Release hardware resources on all exit paths
        for dht_device in dht_devices:
            try:
                dht_device.exit()
            except Exception:
                pass
        print("\nProgram terminated cleanly.")

