import time

from smbus2 import SMBus

I2C_BUS = 1
I2C_ADDR = 0x27
READ_INTERVAL = 2.0
MAX_RETRIES = 3

running = True
bus = None


def handle_signal(signum, frame):
    global running
    running = False


def read_pcf8574(bus):
    """Read a byte from the PCF8574; return None on failure."""
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            return bus.read_byte(I2C_ADDR)
        except OSError:
            if attempt < MAX_RETRIES:
                time.sleep(0.1)
            else:
                print(f"Error: PCF8574 at 0x{I2C_ADDR:02X} did not respond (max retries reached).", file=sys.stderr)
                return None
        except Exception as exc:
            print(f"Error: unexpected I2C failure: {exc}", file=sys.stderr)
            return None
    return None


def main():
    global bus
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            raw = read_pcf8574(bus)
            if raw is None:
                time.sleep(READ_INTERVAL)
                continue

            # Example: assume the first byte is the measurement
            value = raw & 0xFF
            print(f"Measurement: {value:03X}")

            time.sleep(READ_INTERVAL)
    finally:
        if bus is not None:
            bus.close()
        print("Program terminated.")


if __name__ == "__main__":
    main()

import sys
import signal
import time

try:
    from picamera2 import Picamera2
except ImportError:
    print("Error: picamera2 is not installed. Install with: pip install picamera2", file=sys.stderr)
    sys.exit(1)

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

signal.signal(signal.SIGINT, _handle_signal)
signal.signal(signal.SIGTERM, _handle_signal)

def capture_image():
    picam2 = None
    try:
        picam2 = Picamera2()
        # Configure for a still capture; preview configuration is a safe default.
        config = picam2.create_still_configuration()
        picam2.configure(config)
        picam2.start()
        time.sleep(0.5)  # Allow the sensor to warm up / auto-exposure to settle.

        if not _running:
            print("Interrupted before capture.", file=sys.stderr)
            return

        picam2.capture_file("image.jpg")
        print("Image captured successfully.")

    except Exception as e:
        print(f"Error: Failed to capture image: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if picam2 is not None:
            try:
                picam2.stop()
            except Exception:
                pass
            try:
                picam2.close()
            except Exception:
                pass

if __name__ == "__main__":
    capture_image()

import time
import signal
import sys
import board
import busio
import digitalio
import adafruit_mcp3xxx.mcp3008 as MCP
from adafruit_mcp3xxx.analog_in import AnalogIn

SAMPLE_COUNT = 5
SAMPLE_INTERVAL = 300  # seconds

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_adc(channel: int) -> int:
    """Read a single channel from the MCP3008. Returns 0 on error."""
    try:
        ina = AnalogIn(MCP.A0, MCP.A1, MCP.A2)
        return ina.value
    except Exception as exc:
        print(f"Error reading ADC channel {channel}: {exc}", file=sys.stderr)
        return 0

def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        adc = MCP.MCP3008(i2c, channel=0)
    except Exception as exc:
        print(f"Failed to initialize MCP3008: {exc}", file=sys.stderr)
        return 1

    try:
        for i in range(SAMPLE_COUNT):
            if not _running:
                print("Interrupted by signal; exiting early.", file=sys.stderr)
                return 130
            value = read_adc(i)
            if value < 0:
                print(f"Reading {i} failed; skipping.", file=sys.stderr)
            else:
                print(f"Reading {i}: {value}")
            if i < SAMPLE_COUNT - 1 and _running:
                time.sleep(SAMPLE_INTERVAL)
    except Exception as exc:
        print(f"Unexpected error during sampling: {exc}", file=sys.stderr)
        return 1
    finally:
        try:
            i2c.deinit()
        except Exception:
            pass
    return 0

if __name__ == "__main__":
    sys.exit(main())

import time
import signal
import sys
import board
import adafruit_dht

# DHT22 data pins (BCM numbering) on the Raspberry Pi
DATA_PINS = [board.D4, board.D17, board.D18, board.D22, board.D23, board.D27]

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_dht22(pin):
    """Read temperature and humidity from a DHT22 sensor on the given pin."""
    try:
        dht = adafruit_dht.DHT22(pin, use_pulseio=False)
        temperature = dht.temperature
        humidity = dht.humidity
        dht.exit()
        if temperature is None or humidity is None:
            raise RuntimeError("Sensor returned None for temperature or humidity")
        return temperature, humidity
    except Exception as e:
        raise RuntimeError(f"Failed to read DHT22 on pin {pin}: {e}")

def apply_state(temperature, humidity):
    """Print the current state of the DHT22 sensor."""
    print(f"DHT22 State: Temperature = {temperature:.1f} C, Humidity = {humidity:.1f} %")

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        dht22_sensors = []
        for pin in DATA_PINS:
            try:
                dht = adafruit_dht.DHT22(pin, use_pulseio=False)
                dht22_sensors.append(dht)
            except Exception as e:
                print(f"Warning: Failed to initialize DHT22 on pin {pin}: {e}")
                dht22_sensors.append(None)

        if not dht22_sensors:
            print("Error: No DHT22 sensors initialized successfully.")
            return

        for cycle in range(3):
            if not _running:
                break

            for i, dht in enumerate(dht22_sensors):
                if dht is None:
                    continue
                temperature, humidity = read_dht22(dht)
                apply_state(temperature, humidity)

            if not _running:
                break

            # Wait 5 seconds between cycles, but check for interrupt every 0.1s
            for _ in range(50):
                if not _running:
                    break
                time.sleep(0.1)

    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        for dht in dht22_sensors:
            if dht is not None:
                try:
                    dht.exit()
                except Exception:
                    pass
        print("Program finished.")

if __name__ == "__main__":
    main()

import serial
import time
import signal
import sys

# Configuration
SERIAL_PORT = '/dev/serial0'  # Raspberry Pi primary UART (GPIO 14/15)
BAUD_RATE = 9600
TIMEOUT = 1.0
READ_INTERVAL = 0.5

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def initialize_serial(port, baudrate, timeout):
    """Initialize the serial connection with error handling."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        print(f"Serial connection established on {port} at {baudrate} baud.")
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error initializing serial: {e}", file=sys.stderr)
        return None


def read_data(serial_connection):
    """Read a line from the serial port and return it as a string."""
    try:
        raw = serial_connection.readline()
        if not raw:
            return None  # Timeout, no data
        return raw.decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected read error: {e}", file=sys.stderr)
        return None


def process_data(data):
    """Process the received data and print it."""
    if data:
        print(f"Received: {data}")
    return True


def check_data_validity(data):
    """Check if the data is valid (non-empty)."""
    return data and not data.startswith('#')


def main():
    """Main function to continuously read and process data."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        sys.exit(1)

    try:
        while _running:
            data = read_data(serial_connection)
            if data is None:
                # Device did not respond within timeout; abort loop
                print("Warning: No response from device. Exiting loop.", file=sys.stderr)
                break
            if not check_data_validity(data):
                print("Warning: Invalid data received. Skipping.", file=sys.stderr)
                continue
            process_data(data)
            time.sleep(READ_INTERVAL)
    except Exception as e:
        print(f"Unexpected runtime error: {e}", file=sys.stderr)
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial connection closed.")
        print("Program terminated.")


if __name__ == "__main__":
    main()

import time
import signal
import sys
import board
import adafruit_dht

# DHT22 data pins (BCM numbering)
DHT_PINS = [board.D4, board.D17, board.D27]

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_dht22(pin):
    """Read temperature and humidity from a DHT22 sensor on the given pin."""
    try:
        sensor = adafruit_dht.DHT22(pin, use_pulseio=False)
        temperature = sensor.temperature
        humidity = sensor.humidity
        sensor.exit()
        if temperature is None or humidity is None:
            print(f"Pin {pin}: read failed (None)")
            return None, None
        return temperature, humidity
    except RuntimeError as e:
        # DHT22 checksum errors and transient read failures are common
        print(f"Pin {pin}: read error ({e})")
        return None, None
    except Exception as e:
        print(f"Pin {pin}: unexpected error ({e})")
        return None, None

def apply_state(state):
    """Print the current state of the DHT22 sensors."""
    print(f"DHT22 State: {state}")

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    states = {pin: 0 for pin in DHT_PINS}
    try:
        while _running:
            for pin in DHT_PINS:
                temp, hum = read_dht22(pin)
                if temp is not None and hum is not None:
                    states[pin] = 1
                    apply_state(states)
            time.sleep(1)
    except Exception as e:
        print(f"Fatal error: {e}")
    finally:
        for pin in DHT_PINS:
            try:
                sensor = adafruit_dht.DHT22(pin, use_pulseio=False)
                sensor.exit()
            except Exception:
                pass
        print("DHT22 sensors released. Exiting.")

if __name__ == "__main__":
    main()

import signal
import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

PIN_CONFIG = [15, 20, 21]

_outputs: list[OutputDevice] = []

def cleanup() -> None:
    """Close every OutputDevice so the underlying pins are released."""
    for dev in _outputs:
        try:
            dev.close()
        except Exception:
            pass
    _outputs.clear()

def apply_state(state: dict) -> None:
    """Drive every configured pin to the state values (True=HIGH, False=LOW)."""
    for dev, val in zip(_outputs, state.values()):
        dev.value = 1 if val else 0

def main() -> int:
    # Ensure cleanup runs on SIGINT / SIGTERM
    signal.signal(signal.SIGINT, lambda *_: (cleanup(), sys.exit(130)))
    signal.signal(signal.SIGTERM, lambda *_: (cleanup(), sys.exit(130)))

    try:
        for pin in PIN_CONFIG:
            dev = OutputDevice(pin)
            _outputs.append(dev)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO pins: {exc}", file=sys.stderr)
        cleanup()
        return 1
    except Exception as exc:
        print(f"Unexpected error during GPIO setup: {exc}", file=sys.stderr)
        cleanup()
        return 1

    # Example: apply a state dict (True -> HIGH, False -> LOW)
    applied = {pin: 1 if val else 0 for pin, val in zip(PIN_CONFIG, (True, True, True))}
    print(f"Applied state: {applied}")
    apply_state(applied)

    cleanup()
    return 0

if __name__ == "__main__":
    sys.exit(main())

