import time
import signal
import sys
import board
import adafruit_dht

# --- Configuration -----------------------------------------------------------
DHT_PIN = board.D17  # BCM GPIO 17
CYCLES = 5
DELAY = 0.5

# --- Globals for cleanup -------------------------------------------------------
dht_device = None
running = True


def cleanup():
    """Release hardware resources."""
    global dht_device
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
        dht_device = None


def handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global running
    running = False


def main():
    global dht_device

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    # Initialize the DHT11 on BCM GPIO 17
    try:
        dht_device = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
    except Exception as exc:
        print(f"Failed to initialize DHT11 on GPIO 17: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for cycle in range(1, CYCLES + 1):
            if not running:
                break

            try:
                temperature = dht_device.temperature
                humidity = dht_device.humidity

                if temperature is None or humidity is None:
                    print(f"Cycle {cycle}: device returned None (read failed)")
                else:
                    print(f"Cycle {cycle}: Temp = {temperature:.1f} C  Humidity = {humidity:.1f} %")

            except RuntimeError as exc:
                # DHT11 checksum / timing errors are common; report and continue
                print(f"Cycle {cycle}: read error: {exc}")

            except Exception as exc:
                print(f"Cycle {cycle}: unexpected error: {exc}", file=sys.stderr)

            if cycle < CYCLES and running:
                time.sleep(DELAY)

    finally:
        cleanup()
        print("DHT11 data collection finished.")


if __name__ == "__main__":
    main()

