import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

PIN_LIST = [4, 17, 18, 22, 23, 24, 25, 27]
running = True


def handle_signal(signum, frame):
    global running
    running = False


def main():
    global running

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    outputs = []
    try:
        for pin in PIN_LIST:
            dev = OutputDevice(pin)
            dev.off()
            outputs.append(dev)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO pins: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            applied_states = []
            for dev in outputs:
                try:
                    applied_states.append(int(dev.value))
                except GPIOZeroError as exc:
                    print(f"Error reading GPIO {dev.pin}: {exc}", file=sys.stderr)
                    applied_states.append(None)

            if all(s is not None for s in applied_states):
                print(f"GPIO states: {applied_states}")
            else:
                print("Warning: one or more GPIO reads failed.", file=sys.stderr)

            time.sleep(0.001)
    finally:
        for dev in outputs:
            try:
                dev.close()
            except Exception:
                pass


if __name__ == "__main__":
    main()

import sys
import signal
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

PIN = 24
output = None

def cleanup(signum=None, frame=None):
    global output
    if output is not None:
        try:
            output.close()
        except Exception:
            pass
        output = None
    if signum is not None:
        sys.exit(0)

def main():
    global output
    try:
        output = OutputDevice(PIN)
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Failed to initialize GPIO {PIN}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error initializing GPIO {PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        output.on()
        print(f"GPIO {PIN} set to HIGH")
    except Exception as e:
        print(f"Failed to write to GPIO {PIN}: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        output.off()
        print(f"GPIO {PIN} set to LOW")
    except Exception as e:
        print(f"Failed to write to GPIO {PIN}: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    cleanup()

if __name__ == "__main__":
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    main()

import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# BCM pin assignments
PWM_PINS = [4, 12, 23, 24, 25, 27]
UPDATE_INTERVAL = 2.0

# gpiozero PWMOutputDevice accepts a frequency in Hz; we use 100 Hz for
# compatibility with the original spec and to avoid hardware saturation.
FREQ_HZ = 100

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def apply_pwm_state(pwm_devices, state):
    """Apply a 0/1 state to every PWM device and print the applied values."""
    for dev in pwm_devices:
        try:
            dev.value = state
        except DeviceClosed:
            print(f"Warning: device {dev.pin} is closed; skipping.", file=sys.stderr)
        except GPIOZeroError as exc:
            print(f"Warning: could not write to device {dev.pin}: {exc}", file=sys.stderr)
        else:
            value = int(dev.value)
            print(f"GPIO {dev.pin} -> {value}")
    return state


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    pwm_devices = []
    try:
        for pin in PWM_PINS:
            dev = PWMOutputDevice(pin, frequency=FREQ_HZ, initial_value=0)
            pwm_devices.append(dev)
    except GPIOZeroError as exc:
        print(f"Error: failed to initialize PWM devices: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            applied = apply_pwm_state(pwm_devices, 1)
            time.sleep(UPDATE_INTERVAL)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        for dev in pwm_devices:
            try:
                dev.close()
            except Exception:
                pass
        print("Cleanup complete. Exiting.")


if __name__ == "__main__":
    main()

import time
import signal
import sys
import board
import busio
import adafruit_mcp3xxx.mcp3008 as MCP
from adafruit_mcp3xxx.analog_in import AnalogIn

SAMPLE_INTERVAL_S = 5
MAX_RETRIES = 3

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    adc = None
    try:
        try:
            adc = MCP.MCP3008(
                busio.I2C(board.SCL, board.SDA),
                address=0x68
            )
        except Exception as exc:
            print(f"Failed to initialize MCP3008 at 0x68: {exc}", file=sys.stderr)
            sys.exit(1)

        channel = AnalogIn(adc, 0)
        print("MCP3008 initialized. Reading channel 0 every 5 s. Press Ctrl+C to stop.")

        while _running:
            for attempt in range(1, MAX_RETRIES + 1):
                try:
                    value = channel.value
                    print(f"Channel 0: {value}")
                    break
                except Exception as exc:
                    print(f"Read error (attempt {attempt}/{MAX_RETRIES}): {exc}", file=sys.stderr)
                    if attempt < MAX_RETRIES:
                        time.sleep(1)

            if not _running:
                break

            if attempt < MAX_RETRIES:
                time.sleep(1)

            if _running:
                time.sleep(SAMPLE_INTERVAL_S)

    except Exception as exc:
        print(f"Fatal error: {exc}", file=sys.stderr)
    finally:
        if adc is not None:
            try:
                adc.deinit()
            except Exception:
                pass
        print("\nExiting cleanly.")

if __name__ == "__main__":
    main()

import signal
import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

PIN_LIST = [5, 6, 12]
CYCLES = 3
VALID_PINS = {5, 6, 12}

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def apply_output(pin: int, state: bool) -> bool:
    try:
        dev = OutputDevice(pin)
        dev.value = 1 if state else 0
        print(f"GPIO {pin} set to {state}")
        return True
    except GPIOZeroError as exc:
        print(f"Error writing GPIO {pin}: {exc}", file=sys.stderr)
        return False
    except Exception as exc:
        print(f"Unexpected error on GPIO {pin}: {exc}", file=sys.stderr)
        return False
    finally:
        try:
            dev.close()
        except Exception:
            pass

def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    for pin in PIN_LIST:
        if pin not in VALID_PINS:
            print(f"Invalid pin {pin}; skipping.", file=sys.stderr)
            continue

    try:
        for cycle in range(1, CYCLES + 1):
            if not _running:
                print("Interrupted by signal.", file=sys.stderr)
                return 130

            ok = True
            for pin in PIN_LIST:
                state = 1 if cycle % 2 else 0
                if not apply_output(pin, state):
                    ok = False
                    break

            if not ok:
                print("Cycle failed; aborting.", file=sys.stderr)
                return 1

        print("All cycles completed successfully.")
        return 0

    except Exception as exc:
        print(f"Fatal error: {exc}", file=sys.stderr)
        return 1

if __name__ == "__main__":
    sys.exit(main())

