import signal
import sys
import time

from smbus2 import SMBus

TSL2561_ADDR = 0x39
REG_CONTROL = 0x08
REG_TIMING = 0x09
REG_DATA0 = 0x0C
REG_DATA1 = 0x0D
REG_DATA2 = 0x0E
REG_DATA3 = 0x0F

VALIDITY_BIT = 0x80
SCALE_1X = 0x00
SCALE_2X = 0x01
SCALE_4X = 0x02
SCALE_8X = 0x03
SCALE_16X = 0x04
SCALE_32X = 0x05
SCALE_64X = 0x06
SCALE_128X = 0x07

running = True


def _handle_signal(signum, frame):
    global running
    running = False


def _read_u16(bus, addr, reg):
    data = bus.read_i2c_block_data(addr, reg, 2)
    return (data[0] << 8) | data[1]


def _read_s16(bus, addr, reg):
    val = _read_u16(bus, addr, reg)
    return val if val & 0x8000 else val - 0x10000


def _read_s32(bus, addr, reg):
    val = _read_u16(bus, addr, reg)
    return val if val & 0x80000000 else val - 0x10000000


def _read_s64(bus, addr, reg):
    val = _read_u16(bus, addr, reg)
    return val if val & 0x8000000000000000 else val - 0x1000000000000000


def _read_lut(bus, addr, reg):
    data = bus.read_i2c_block_data(addr, reg, 2)
    return (data[0] << 8) | data[1]


def _read_lut16(bus, addr, reg):
    data = bus.read_i2c_block_data(addr, reg, 2)
    return (data[0] << 8) | data[1]


def _read_lut32(bus, addr, reg):
    data = bus.read_i2c_block_data(addr, reg, 4)
    return (data[0] << 24) | (data[1] << 16) | (data[2] << 8) | data[3]


def _read_lut64(bus, addr, reg):
    data = bus.read_i2c_block_data(addr, reg, 8)
    return (data[0] << 56) | (data[1] << 48) | (data[2] << 40) | (data[3] << 32) | (data[4] << 24) | (data[5] << 16) | (data[6] << 8) | data[7]


def _check_validity(raw):
    return raw & VALIDITY_BIT


def _check_lut16(raw):
    lut = _read_lut16(bus, TSL2561_ADDR, 0x0A)
    return (raw - lut) & 0x3FFF


def _check_lut32(raw):
    lut = _read_lut32(bus, TSL2561_ADDR, 0x0A)
    return (raw - lut) & 0x1FFFFF


def _check_lut64(raw):
    lut = _read_lut64(bus, TSL2561_ADDR, 0x0A)
    return (raw - lut) & 0x7FFFFF


def _read_raw(bus, addr):
    data0 = bus.read_byte_data(addr, REG_DATA0)
    data1 = bus.read_byte_data(addr, REG_DATA1)
    data2 = bus.read_byte_data(addr, REG_DATA2)
    data3 = bus.read_byte_data(addr, REG_DATA3)
    raw = (data0 << 24) | (data1 << 16) | (data2 << 8) | data3
    if _check_validity(raw):
        return raw
    if _check_lut16(raw):
            return _check_lut16(raw)
    if _check_lut32(raw):
            return _check_lut32(raw)
    if _check_lut64(raw):
            return _check_lut64(raw)
    return None


def read_tsl2561(bus):
    raw = _read_raw(bus, TSL2561_ADDR)
    if raw is None:
        return None
    if raw & 0x80000000:
        raw >>= 1
    if raw & 0x40000000:
        raw >>= 1
    if raw & 0x20000000:
        raw >>= 1
    if raw & 0x10000000:
        raw >>= 1
    if raw & 0x08000000:
        raw >>= 1
    if raw & 0x04000000:
        raw >>= 1
    if raw & 0x02000000:
        raw >>= 1
    if raw & 0x01000000:
        raw >>= 1
    if raw & 0x00800000:
        raw >>= 1
    if raw & 0x00080000:
        raw >>= 1
    if raw & 0x00040000:
        raw >>= 1
    if raw & 0x00020000:
        raw >>= 1
    if raw & 0x00010000:
        raw >>= 1
    if raw & 0x00008000:
        raw >>= 1
    if raw & 0x00004000:
        raw >>= 1
    if raw & 0x00002000:
        raw >>= 1
    if raw & 0x00001000:
        raw >>= 1
    if raw & 0x00000C00:
        raw >>= 2
    if raw & 0x000000F0:
        raw >>= 4
    if raw & 0x0000000F:
        raw >>= 5
    if raw & 0x00000007:
        raw >>= 3
    if raw & 0x00000003:
        raw >>= 2
    if raw & 0x00000001:
        raw >>= 1
    return raw


def main():
    global running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    bus = None
    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        bus.write_byte(TSL2561_ADDR, REG_CONTROL | 0x80)
        time.sleep(0.01)
        bus.write_byte(TSL2561_ADDR, REG_TIMING | 0x00)
        time.sleep(0.01)
        print("TSL2561 initialized. Reading every 1 second (Ctrl+C to stop).")
        while running:
            try:
                lux = read_tsl2561(bus)
                if lux is None:
                    print("Error: invalid reading from TSL2561.")
                else:
                    print(f"TSL2561: {lux} lx")
            except OSError as e:
                print(f"I2C communication error: {e}", file=sys.stderr)
            time.sleep(1.0)
    finally:
        if bus is not None:
            bus.close()
        print("\nProgram stopped.")


if __name__ == "__main__":
    main()

