PIN = 14
INTERVAL = 5.0
running = True


def _handle_signal(signum, frame):
    global running
    running = False


def main() -> int:
    global running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        device = PWMOutputDevice(PIN, frequency=1000, initial_value=0.0)
    except (GPIOZeroError, GPIODeviceError) as exc:
        print(f"Error: failed to initialize PWM on GPIO {PIN}: {exc}", file=sys.stderr)
        return 1
    except Exception as exc:
        print(f"Error: unexpected failure initializing GPIO {PIN}: {exc}", file=sys.stderr)
        return 1

    try:
        while running:
            try:
                duty = device.value
            except Exception as exc:
                print(f"Warning: read failed ({exc}); skipping cycle.", file=sys.stderr)
                time.sleep(INTERVAL)
                continue

            if not isinstance(duty, (int, float)):
                print(f"Warning: invalid duty value ({type(duty)}); skipping cycle.", file=sys.stderr)
                time.sleep(INTERVAL)
