import signal
import sys
import time

from gpiozero import DistanceSensor

# --- Configuration -----------------------------------------------------------
SOUND_SPEED_OF_SOUND = 34300          # m/s
DISTANCE_SCALE_FACTOR = 0.034         # m per raw count
SAMPLE_INTERVAL = 0.1                # seconds between readings
NUM_READINGS = 10
MAX_DISTANCE_M = 4.0                 # HC-SR04 practical range

# --- Globals for cleanup -----------------------------------------------------
sensor = None
running = True


def _cleanup(signum=None, frame=None):
    """Release hardware resources on exit or interrupt."""
    global sensor, running
    running = False
    if sensor is not None:
        try:
            sensor.close()
        except Exception:
            pass
        sensor = None
    if signum is not None:
        sys.exit(0)


def read_distance(sensor):
    """Return distance in metres, or None if the reading is invalid."""
    try:
        raw = sensor.distance
    except Exception as exc:
        print(f"Warning: sensor read failed: {exc}", file=sys.stderr)
        return None

    if raw is None or raw < 0 or raw > 4.0:
        print("Warning: invalid distance reading (out of range)", file=sys.stderr)
        return None

    distance = raw * DISTANCE_SCALE_FACTOR
    return distance


def main():
    global sensor

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    try:
        sensor = DistanceSensor(echo=4, trigger=3, max_distance=MAX_DISTANCE_M)
    except Exception as exc:
        print(f"Error: failed to initialise HC-SR04: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(NUM_READINGS):
            if not running:
                break

            distance = read_distance(sensor)
            if distance is None:
                print("Warning: invalid reading, skipping cycle", file=sys.stderr)
            else:
                print(f"Reading {i + 1}/{NUM_READINGS} -> {distance:.2f} m")
            time.sleep(SAMPLE_INTERVAL)

    except Exception as exc:
        print(f"Error during measurement loop: {exc}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

