    except GPIOZeroError as e:
        print(f"Failed to initialize GPIO {PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        output.on()
        print(f"GPIO {PIN} set to HIGH")
    except GPIOZeroError as e:
        print(f"Failed to write to GPIO {PIN}: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        value = output.value
    except GPIOZeroError as e:
        print(f"Failed to read GPIO {PIN}: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    if not isinstance(value, bool) or value is None:
        print(f"Invalid reading from GPIO {PIN}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    print(f"GPIO {PIN} state: {value}")

    cleanup()

if __name__ == "__main__":
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    main()

import signal
import sys
import time

try:
    from smbus2 import SMBus
except ImportError:
    print("Error: smbus2 library not installed. Install with: pip install smbus2")
    sys.exit(1)

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
ACCEL_XOUT_H = 0x3B
ACCEL_XOUT_L = 0x3C
ACCEL_RNG = 0x3D
ACCEL_LSB_RANGE = 0x2D
ACCEL_SCALE = 0.004  # LSB/g for +/-2g range

running = True
bus = None


def handle_signal(signum, frame):
    global running
    running = False


signal.signal(signal.SIGINT, handle_signal)
signal.signal(signal.SIGTERM, handle_signal)


def read_raw_accel():
    """Read raw 16-bit signed acceleration from ACCEL_XOUT_H/L."""
    try:
        high = bus.read_byte_data(MPU6050_ADDR, ACCEL_XOUT_H)
        low = bus.read_byte_data(MPU6050_ADDR, ACCEL_XOUT_L)
    except OSError as e:
        print(f"I2C read error: {e}")
        return None

    value = (high << 8) | low
    if value >= 0x8000:
        value -= 0x10000
    return value


def check_accel_validity(raw):
    """Return True if the raw acceleration value is within the sensor's range."""
    if raw is None:
        return False
    if not (0 <= raw <= 0x7FFF):
        return False
    return True


def main():
    global bus

    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}")
        sys.exit(1)

    try:
        # Verify device presence by reading PWR_MGMT_1 register
        try:
            bus.read_byte_data(MPU6050_ADDR, PWR_MGMT_1)
        except OSError:
            print(f"Error: MPU6050 not found at address 0x{MPU6050_ADDR:02X}.")
            sys.exit(1)

        print("Starting MPU6050 readings (8 samples, 0.1 s interval)...")
        for i in range(8):
            if not running:
                print("Interrupted by user.")
                break

            raw = read_raw_accel()
            if not check_accel_validity(raw):
                print(f"Sample {i+1}: invalid acceleration reading, skipping.")
                continue

            accel_x = raw / ACCEL_SCALE
            print(f"Sample {i+1}: Accel X = {accel_x:.3f} g")

            if i < 7:
                time.sleep(0.1)

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass
        print("Program finished.")


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import OutputDevice, Device
from gpiozero.pins.native import NativeFactory

# Use the native pin factory so the script runs on Pi without pigpio daemon.
Device.pin_factory = NativeFactory()

# HC-SR04 trigger and echo pins (BCM numbering)
TRIG_PINS = [5, 6, 17, 18, 22, 23, 24, 27]
ECHO_PINS = [6, 5, 18, 17, 23, 22, 24, 27]

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running

    # Register signal handlers for clean shutdown
    for sig in (signal.SIGINT, signal.SIGTERM):
        signal.signal(sig, _handle_signal)

    # Initialize trigger pins as outputs, initially LOW
    triggers = []
    for pin in TRIG_PINS:
        try:
            t = OutputDevice(pin, initial_value=False)
            triggers.append(t)
        except Exception as e:
            print(f"Error initializing trigger pin GPIO{pin}: {e}", file=sys.stderr)
            return 1

    # Initialize echo pins as inputs (pull-down for stability)
    echoes = []
    for pin in ECHO_PINS:
        try:
            e = OutputDevice(pin, initial_value=False, active_high=True, pull_up=False)
            echoes.append(e)
        except Exception as e:
            print(f"Error initializing echo pin GPIO{pin}: {e}", file=sys.stderr)
            return 1

    # Allow the sensor to settle after power-up
    time.sleep(0.1)

    # Send 10 pulses and measure echo rise time
    for _ in range(10):
        if not _running:
            break
        for t in triggers:
            t.off()
        time.sleep(0.000002)  # 2 µs settle between pulses
        for t in triggers:
            t.on()
        time.sleep(0.00001)   # 10 µs pulse width
        for t in triggers:
            t.off()

        # Wait for echo to go HIGH with timeout
        deadline = time.time() + 0.1
        while not any(e.is_active for e in echoes):
            if time.time() > deadline:
                print(f"Timeout waiting for echo on GPIO{ECHO_PINS.index(e.pin)}", file=sys.stderr)
                break
        else:
            # Measure how long the echo stays HIGH
            start = time.time()
            while e.is_active:
                if time.time() - start > 0.1:
                    break
            else:
                # Also catch the echo falling below threshold
                while not e.is_active:
                    if time.time() - start > 0.1:
                        break
            distance = (time.time() - start) * 17150  # Speed of sound ~343 m/s
            print(f"Measured Distance: {distance:.2f} cm")

    # Cleanup
    for t in triggers:
        t.close()
    for e in echoes:
        e.close()
    print("GPIO cleanup completed.")
    return 0

if __name__ == "__main__":
    sys.exit(main())

