import signal
import sys
import time

from smbus2 import SMBus

BME280_I2C_ADDR = 0x76
READ_INTERVAL_S = 2
NUM_READINGS = 5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_bme280_temperature(bus):
    """Return the BME280 temperature in degrees Celsius, or None on error."""
    try:
        raw = bus.read_i2c_block_data(BME280_I2C_ADDR, 0x88, 3)
        if len(raw) < 3:
            print("Error: incomplete temperature data read.")
            return None
        data = (raw[0] << 8) | raw[1]
        if data & 0x8000:
            data -= 1 << 16
        temp = (data >> 4) * 100.0
        return temp
    except OSError as e:
        print(f"I2C read error: {e}")
        return None


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}")
        sys.exit(1)

    try:
        for i in range(NUM_READINGS):
            if not _running:
                print("Interrupted by user.")
                break
            temp = read_bme280_temperature(bus)
            if temp is not None:
                print(f"Reading {i + 1}/{NUM_READINGS} - Temperature: {temp:.2f} C")
            else:
                print(f"Reading {i + 1}/{NUM_READINGS} - Temperature: ERROR")
            if i < NUM_READINGS - 1 and _running:
                time.sleep(READ_INTERVAL_S)
    finally:
        bus.close()
        print("I2C bus released.")


if __name__ == "__main__":
    main()

