import time
import signal
import sys
import board
import busio
import digitalio
import adafruit_mcp3xxx.mcp3008 as MCP
from adafruit_mcp3xxx.analog_in import AnalogIn

SAMPLE_INTERVAL = 5.0
MAX_RETRIES = 3

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_adc(channel: int) -> int:
    """Read a single channel from the MCP3008; return None on failure."""
    try:
        chan = AnalogIn(MCP.A0, MCP.A1, MCP.A2, channel=channel)
        return chan.value
    except Exception as exc:
        print(f"Error reading ADC channel {channel}: {exc}", file=sys.stderr)
        return None

def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        adc = MCP.MCP3008(i2c, channel=0)
    except Exception as exc:
        print(f"Failed to initialize MCP3008: {exc}", file=sys.stderr)
        return 1

    try:
        while _running:
            for attempt in range(1, MAX_RETRIES + 1):
                if not _running:
                    break
                value = read_adc(0)
                if value is not None:
                    print(f"ADC Channel 0: {value}")
                    break
                print(f"ADC Channel 0: read failed (attempt {attempt}/{MAX_RETRIES})", file=sys.stderr)
                if attempt < MAX_RETRIES:
                    time.sleep(0.5)
            if not _running:
                break
            time.sleep(SAMPLE_INTERVAL)
    finally:
        try:
            i2c.deinit()
        except Exception:
            pass
    return 0

if __name__ == "__main__":
    sys.exit(main())

