import signal
import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

PIN_A = 17
PIN_B = 18

running = True

def _handle_signal(signum, frame):
    global running
    running = False

def main():
    global running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        a = OutputDevice(PIN_A)
        b = OutputDevice(PIN_B)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO pins: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        a.off()
        b.off()
        print("GPIO initialized: pins 17 and 18 OFF")

        while running:
            try:
                a_on = a.is_active
                b_on = b.is_active

                if not a_on and not b_on:
                    print("GPIO 17:OFF, GPIO 18:OFF")
                elif a_on and not b_on:
                    print("GPIO 17:ON, GPIO 18:OFF")
                elif not a_on and b_on:
                    print("GPIO 17:OFF, GPIO 18:ON")
                else:
                    print("GPIO 17:ON, GPIO 18:ON")

            except GPIOZeroError as exc:
                print(f"GPIO read error: {exc}", file=sys.stderr)
                break

    finally:
        try:
            a.close()
            b.close()
        except Exception:
            pass
        print("GPIO cleanup completed")

if __name__ == "__main__":
    main()
